package dev.underthebedrock.horror;
import dev.underthebedrock.UnderTheBedrockPlugin; import dev.underthebedrock.world.VoidWorldManager;
import org.bukkit.Location; import org.bukkit.Sound; import org.bukkit.entity.Player; import org.bukkit.event.EventHandler; import org.bukkit.event.Listener; import org.bukkit.event.player.AsyncPlayerChatEvent; import org.bukkit.event.player.PlayerQuitEvent; import org.bukkit.scheduler.BukkitTask;
import java.util.EnumMap; import java.util.HashMap; import java.util.Map; import java.util.Optional; import java.util.Random; import java.util.UUID;
/** Per-player occurrence pacing and the central distance gate for future entity controllers. */
public final class OccurrenceDirector implements Listener {
 private final long intervalTicks,minGapMs,severeGapMs,entityCooldownMs; private final double rollChance; private final EntityEncounterPolicy entityPolicy;
 private final UnderTheBedrockPlugin plugin; private final VoidWorldManager worlds; private final PlayerHorrorMemoryStore store; private final Map<UUID,PlayerHorrorMemory> memories=new HashMap<>(); private final Map<UUID,Location> lastLocations=new HashMap<>(); private final Random random=new Random(); private BukkitTask task;
 public OccurrenceDirector(UnderTheBedrockPlugin p,VoidWorldManager w,PlayerHorrorMemoryStore s){plugin=p;worlds=w;store=s;intervalTicks=Math.max(1,p.getConfig().getLong("horror.director.check-interval-seconds",12))*20L;minGapMs=Math.max(1,p.getConfig().getLong("horror.director.minimum-occurrence-gap-seconds",42))*1000L;severeGapMs=Math.max(1,p.getConfig().getLong("horror.director.severe-occurrence-cooldown-minutes",8))*60_000L;rollChance=Math.max(0,Math.min(1,p.getConfig().getDouble("horror.director.base-roll-chance",.22)));entityCooldownMs=Math.max(1,p.getConfig().getLong("horror.entities.successful-encounter-cooldown-minutes",8))*60_000L;entityPolicy=new EntityEncounterPolicy(p.getConfig().getDouble("horror.entities.safe-radius-blocks",512),p.getConfig().getDouble("horror.entities.full-threat-distance-blocks",8192),p.getConfig().getDouble("horror.entities.maximum-chance-per-check",.025));}
 public void start(){if(task!=null)return;plugin.getServer().getPluginManager().registerEvents(this,plugin);task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,intervalTicks,intervalTicks);}
 public void stop(){if(task!=null)task.cancel();task=null;for(var e:memories.entrySet())store.save(e.getKey(),e.getValue());memories.clear();lastLocations.clear();}
 public PlayerHorrorMemory memory(UUID id){return memories.computeIfAbsent(id,store::load);}
 public String status(Player p){PlayerHorrorMemory m=memory(p.getUniqueId());return String.format("§7Tension: §f%.1f §8| §7Encounters: §f%d §8| §7Last: §f%s",m.tension(),m.encounters(),m.lastOccurrence());}
 /** Called by entity controllers; returns empty until depth, rarity, and per-player cooldown all permit an encounter. */
 public Optional<EntityArchetype> trySelectEntityEncounter(Player player){if(!worlds.isActive()||!player.getWorld().equals(worlds.getWorld()))return Optional.empty();Location entrance=worlds.getWorld().getSpawnLocation();double dx=player.getLocation().getX()-entrance.getX(),dz=player.getLocation().getZ()-entrance.getZ();double distance=Math.hypot(dx,dz);PlayerHorrorMemory m=memory(player.getUniqueId());long now=System.currentTimeMillis();if(now-m.lastEntityEncounterAt()<entityCooldownMs)return Optional.empty();Optional<EntityArchetype> selected=entityPolicy.roll(distance,random);selected.ifPresent(type->{m.recordEntity(type,now);store.save(player.getUniqueId(),m);});return selected;}
 public double entityChanceAt(Player player){if(!player.getWorld().equals(worlds.getWorld()))return 0;Location entrance=worlds.getWorld().getSpawnLocation();return entityPolicy.chanceAt(Math.hypot(player.getLocation().getX()-entrance.getX(),player.getLocation().getZ()-entrance.getZ()));}
 private void tick(){if(!worlds.isActive())return;var world=worlds.getWorld();if(world==null)return;long now=System.currentTimeMillis();for(Player p:world.getPlayers()){PlayerHorrorMemory m=memory(p.getUniqueId());Location current=p.getLocation();Location previous=lastLocations.put(p.getUniqueId(),current.clone());if(previous!=null&&previous.getWorld().equals(current.getWorld()))m.addDistance((long)Math.sqrt(previous.distanceSquared(current)));m.relax();if(now-m.lastOccurrenceAt()<minGapMs||random.nextDouble()>rollChance)continue;deliver(p,m,chooseSeverity(m,now),now);if(m.encounters()%3==0)store.save(p.getUniqueId(),m);}}
 private OccurrenceSeverity chooseSeverity(PlayerHorrorMemory m,long now){Map<OccurrenceSeverity,Double> weights=new EnumMap<>(OccurrenceSeverity.class);boolean severeReady=now-m.lastSevereOccurrenceAt()>=severeGapMs;double total=0;for(OccurrenceSeverity s:OccurrenceSeverity.values()){double w=s.baseWeight()*(1+(m.tension()/100)*s.rank()*.7)*(1+(m.provocation()/100)*s.rank()*.9);if(s.rank()>=4&&!severeReady)w=0;if(s==OccurrenceSeverity.TERRIFYING&&(m.tension()<70||m.provocation()<45))w=0;weights.put(s,w);total+=w;}double roll=random.nextDouble()*total;for(OccurrenceSeverity s:OccurrenceSeverity.values()){roll-=weights.get(s);if(roll<=0)return s;}return OccurrenceSeverity.NORMAL;}
 private void deliver(Player p,PlayerHorrorMemory m,OccurrenceSeverity s,long now){String id;switch(s){
 case NORMAL->{id="distant_environment";if(random.nextBoolean())p.playSound(p.getLocation(),Sound.AMBIENT_CAVE,.16f,.75f);}
 case ODD->{id="unseen_movement";p.playSound(p.getLocation(),Sound.BLOCK_WOODEN_DOOR_OPEN,.22f,.65f);}
 case STRANGE->{id="familiar_footsteps";Location behind=p.getLocation().subtract(p.getLocation().getDirection().multiply(5));p.playSound(behind,Sound.BLOCK_STONE_STEP,.42f,.72f);}
 case WEIRD->{id="presence_nearby";p.playSound(p.getLocation(),Sound.ENTITY_ENDERMAN_STARE,.28f,.65f);p.sendMessage("§8You get the feeling something was just here.");}
 case SCARY->{id="close_observer";p.playSound(p.getLocation(),Sound.ENTITY_WARDEN_HEARTBEAT,.24f,.8f);p.sendMessage("§8For a moment, the darkness feels occupied.");}
 case TERRIFYING->{id="deep_attention";p.playSound(p.getLocation(),Sound.ENTITY_WARDEN_HEARTBEAT,.5f,.55f);p.sendMessage("§8§oIt knows you are looking.");}
 default->{return;}}m.recordOccurrence(id,s,now);}
 @EventHandler public void onChat(AsyncPlayerChatEvent event){String msg=event.getMessage().toLowerCase(java.util.Locale.ROOT);double amount=0;if(has(msg,"null","where are you","come here","show yourself"))amount+=2.5;if(has(msg,"hate you","stupid","kill you","you can't","coward"))amount+=5;if(has(msg,"i am not scared","not afraid","i know you're there"))amount+=3;if(amount<=0)return;final double provocation=amount;UUID id=event.getPlayer().getUniqueId();plugin.getServer().getScheduler().runTask(plugin,()->{Player active=plugin.getServer().getPlayer(id);if(active==null||!active.getWorld().equals(worlds.getWorld()))return;PlayerHorrorMemory m=memory(id);m.provoke(provocation);m.addTension(1.2);m.recordChat(System.currentTimeMillis());if(m.provocation()>=18&&random.nextDouble()<.2){Player p=plugin.getServer().getPlayer(id);if(p!=null&&p.getWorld().equals(worlds.getWorld())){p.playSound(p.getLocation(),Sound.ENTITY_ENDERMAN_STARE,.32f,.55f);p.sendMessage("§8§oSomething heard that.");m.addTension(1.0);}}store.save(id,m);});}
 @EventHandler public void onQuit(PlayerQuitEvent event){UUID id=event.getPlayer().getUniqueId();PlayerHorrorMemory m=memories.remove(id);lastLocations.remove(id);if(m!=null)store.save(id,m);}
 private boolean has(String text,String...terms){for(String term:terms)if(text.contains(term))return true;return false;}
}
